mapper.select:
SELECT tdm31_company_id
  FROM tdm31_role_desc
 WHERE tdm31_role_desc_id = #{roleDescId}

SELECT tdm31_role_desc_id AS role_desc_id, TO_CHAR(tdm31_reg_date, 'YYYY-MM-DD') AS reg_date, tdm31_reason_nm AS reason_name, tdm31_company_id AS company_id, tdm31_company_nm AS company_name, tdm31_person_id AS person_id, tdm31_person_nm AS person_name, TO_CHAR(tdm31_allc_std_date, 'YYYY-MM-DD') AS allc_std_date, tdm31_role_nm AS role_name, tdm31_add_title AS add_title, tdm31_appr_id AS appr_id, tdm31_appr_status_cd AS appr_status_code, tdm31_appr_status_nm AS appr_status_name FROM ( SELECT tdm31_role_desc.* , f_cdnm('TdmDescRegReason', tdm31_reason_cd, tdm31_company_id, tdm31_reg_date) AS tdm31_reason_nm --생성사유 , tdm01_person_nm AS tdm31_person_nm --임원명 , f_get_company_nm(tdm31_company_id) AS tdm31_company_nm --회사명 , tdm20_role_id AS tdm31_role_id --직책ID , tdm20_role_nm AS tdm31_role_nm --직책 , f_get_tdmPersonInfo(tdm31_person_id, tdm31_allc_std_date, '1') AS tdm31_add_title --겸직사항 , COALESCE(apr01_status_cd, '00') AS tdm31_appr_status_cd --결재상태코드 , f_cdnm('AprStatusCode', apr01_status_cd, tdm31_company_id, tdm31_reg_date) AS tdm31_appr_status_nm --결재상태명 FROM tdm31_role_desc INNER JOIN LATERAL getTdm30RoleAllc(tdm31_company_id, tdm31_allc_std_date, true) ON tdm30_role_allc_id = tdm31_role_allc_id INNER JOIN tdm20_role ON tdm20_role_id = tdm30_role_id INNER JOIN tdm01_hr ON tdm01_person_id = tdm31_person_id LEFT OUTER JOIN apr01_appr ON apr01_appr_id = tdm31_appr_id WHERE 1=1
AND tdm31_company_id = #{companyId}
AND tdm31_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)
AND COALESCE(apr01_status_cd, '00') IN ('10','20','30')
) t WHERE CONCAT(tdm31_role_nm, tdm31_add_title, tdm31_person_nm) ILIKE #{searchText} ORDER BY tdm31_company_id, tdm31_reg_date, tdm31_person_nm COLLATE "ko-KR-x-icu"

SELECT tdm31_role_desc_id AS role_desc_id, TO_CHAR(tdm31_reg_date, 'YYYY-MM-DD') AS reg_date, tdm31_reason_cd AS reason_code, tdm31_reason_nm AS reason_name, tdm31_company_id AS company_id, tdm31_person_id AS person_id, tdm31_person_nm AS person_name, tdm31_role_allc_id AS role_allc_id, TO_CHAR(tdm31_allc_std_date, 'YYYY-MM-DD') AS allc_std_date, tdm31_role_nm AS role_name, tdm31_add_title AS add_title, tdm31_appr_id AS appr_id, tdm31_appr_status_cd AS appr_status_code, tdm31_appr_status_nm AS appr_status_name FROM ( SELECT tdm31_role_desc.* , f_cdnm('TdmDescRegReason', tdm31_reason_cd, tdm31_company_id, tdm31_reg_date) AS tdm31_reason_nm --생성사유 , tdm01_person_nm AS tdm31_person_nm --임원명 , tdm20_role_nm AS tdm31_role_nm --직책 , f_get_tdmPersonInfo(tdm31_person_id, tdm31_allc_std_date, '1') AS tdm31_add_title --겸직사항 , COALESCE(apr01_status_cd, '00') AS tdm31_appr_status_cd --결재상태코드 , f_cdnm('AprStatusCode', apr01_status_cd, tdm31_company_id, tdm31_reg_date) AS tdm31_appr_status_nm --결재상태명 FROM tdm31_role_desc INNER JOIN LATERAL getTdm30RoleAllc(tdm31_company_id, tdm31_allc_std_date, true) ON tdm30_role_allc_id = tdm31_role_allc_id INNER JOIN tdm20_role ON tdm20_role_id = tdm30_role_id INNER JOIN tdm01_hr ON tdm01_person_id = tdm31_person_id LEFT OUTER JOIN apr01_appr ON apr01_appr_id = tdm31_appr_id WHERE tdm31_company_id = #{companyId}
AND tdm31_reg_date BETWEEN CAST(#{startDate} AS date) AND CAST(#{closeDate} AS date)
AND COALESCE(apr01_status_cd, '00') NOT IN ('30')
) t WHERE CONCAT(tdm31_role_nm, tdm31_add_title, tdm31_person_nm) ILIKE #{searchText} ORDER BY tdm31_reg_date DESC, tdm31_person_nm COLLATE "ko_KR.utf8"

mapper.update:
UPDATE tdm31_role_desc
   SET tdm31_reg_date  = #{regDate}
     , tdm31_reason_cd = #{reasonCode}
     , tdm31_upd_nm    = #{updName}
     , tdm31_upd_date  = f_sysdate()
 WHERE tdm31_role_desc_id = #{roleDescId}
   AND tdm31_company_id   = #{companyId}

